/* xx_romfs_extractor.c - search raw data for ROMFS.
 *
 * Scans for:
 *   2D 72 6F 6D 31 66 73 2D at +0  ("-rom1fs-")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the romfs reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/romfs/xx_romfs.h"

static const uint8_t k_anchor0[] = { 0x2D, 0x72, 0x6F, 0x6D, 0x31, 0x66, 0x73, 0x2D };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_ROMFS };

static Abstractformat *xx_romfs_search_open(xx_io_device *window) {
    xx_romfs *reader = xx_romfs_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_romfs_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_romfs_free((xx_romfs *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_romfs_search_open, xx_romfs_search_close
};

static xx_format_search_state *xx_romfs_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_romfs_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_romfs_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_romfs_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_romfs_extractor = {
    xx_romfs_create_format_search,
    xx_romfs_get_current_format_info,
    xx_romfs_format_search_find_next,
    xx_romfs_free_format_search
};
